class Solution {
public:
    int componentValue(std::vector<int>& nums, std::vector<std::vector<int>>& edges) {
        int total_sum = std::accumulate(nums.begin(), nums.end(), 0);
        int max_val = *std::max_element(nums.begin(), nums.end());
        int n = nums.size();
        std::vector<std::vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }

        auto check = [&](int target) {
            bool valid = true;
            std::function<int(int, int)> dfs = [&](int u, int p) {
                if (!valid) return 0;
                int s = nums[u];
                for (int v : adj[u]) {
                    if (v != p) s += dfs(v, u);
                }
                if (s > target) valid = false;
                return s == target ? 0 : s;
            };
            int rem = dfs(0, -1);
            return valid && rem == 0;
        };

        for (int parts = n; parts > 1; parts--) {
            if (total_sum % parts == 0) {
                int target = total_sum / parts;
                if (target >= max_val && check(target)) {
                    return parts - 1;
                }
            }
        }
        return 0;
    }
};

class Solution {
    public int componentValue(int[] nums, int[][] edges) {
        int totalSum = 0, maxVal = 0;
        for (int x : nums) {
            totalSum += x;
            if (x > maxVal) maxVal = x;
        }
        int n = nums.length;
        java.util.List<java.util.List<Integer>> adj = new java.util.ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new java.util.ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }

        for (int parts = n; parts > 1; parts--) {
            if (totalSum % parts == 0) {
                int target = totalSum / parts;
                if (target >= maxVal && check(nums, adj, target)) {
                    return parts - 1;
                }
            }
        }
        return 0;
    }

    private boolean check(int[] nums, java.util.List<java.util.List<Integer>> adj, int target) {
        boolean[] valid = new boolean[]{true};
        int rem = dfs(0, -1, nums, adj, target, valid);
        return valid[0] && rem == 0;
    }

    private int dfs(int u, int p, int[] nums, java.util.List<java.util.List<Integer>> adj, int target, boolean[] valid) {
        if (!valid[0]) return 0;
        int s = nums[u];
        for (int v : adj.get(u)) {
            if (v != p) s += dfs(v, u, nums, adj, target, valid);
        }
        if (s > target) valid[0] = false;
        return s == target ? 0 : s;
    }
}

var componentValue = function(nums, edges) {
    const totalSum = nums.reduce((a, b) => a + b, 0);
    const maxVal = Math.max(...nums);
    const n = nums.length;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    function check(target) {
        let valid = true;
        function dfs(u, p) {
            if (!valid) return 0;
            let s = nums[u];
            for (const v of adj[u]) {
                if (v !== p) s += dfs(v, u);
            }
            if (s > target) valid = false;
            return s === target ? 0 : s;
        }
        const rem = dfs(0, -1);
        return valid && rem === 0;
    }

    for (let parts = n; parts > 1; parts--) {
        if (totalSum % parts === 0) {
            const target = totalSum / parts;
            if (target >= maxVal && check(target)) {
                return parts - 1;
            }
        }
    }
    return 0;
};
